**4. Implement the type**

Follow the constructor pattern:

```typescript
// src/nonempty/index.ts
import { Base } from "@/core/base"
import type { Functor, Applicative } from "@/functor"

export type NonEmptyListType<T> = Functor<T> & Applicative<T> & {
  head: T
  tail: T[]
  get length(): number
}

export function NonEmptyList<T>(head: T, tail: T[]): NonEmptyListType<T> {
  return Base("NonEmptyList", {
    head,
    tail,

    // Functor
    map: <B>(f: (val: T) => B): NonEmptyListType<B> => {
      return NonEmptyList(f(head), tail.map(f))
    },

    // Applicative
    ap: <B>(ff: Applicative<(val: T) => B>): NonEmptyListType<B> => {
      // Apply functions from the applicative
      const headFn = (ff as any).head
      const tailFns = (ff as any).tail || []
      return NonEmptyList(
        (headFn as (val: T) => B)(head),
        tail.map((v, i) => (tailFns[i] || headFn)(v))
      )
    },

    // Helper
    get length() { return 1 + tail.length },

    // Pipe for composition
    pipe: () => ({
      map: (f: (val: T) => any) => NonEmptyList(head, tail).map(f),
      flatMap: (f: (val: T) => any) => {
        const mapped = f(head)
        const rest = tail.map(f)
        // Flatten into a single NonEmptyList
        const all = [mapped, ...rest]
        return all.reduce((acc, cur) => {
          // Append all elements from cur
          return NonEmptyList(acc.head, [...acc.tail, cur.head, ...cur.tail])
        })
      }
    }),
  })
}

// Companion methods
NonEmptyList.of = <T>(first: T, ...rest: T[]): NonEmptyListType<T> => {
  return NonEmptyList(first, rest)
}

NonEmptyList.fromArray = <T>(arr: T[]): Maybe<NonEmptyListType<T>> => {
  if (arr.length === 0) return Option.none()
  return Option.some(NonEmptyList(arr[0], arr.slice(1)))
}
```

